import useGetApiData from '@/hooks/pro/useGetApiData'
import useProHelper from '@/hooks/pro/useProHelper'
import useProListStore from '@/store/pro/list'
import { ProCoinListFetchParams } from '@/types/pro'
import { TableSortTh, useTokenSelect } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { useAccountStore } from '@cetus/stores'
import useTokenSelectStore from '@cetus/stores/src/useTokenSelectStore'
import { Token } from '@cetus/types'
import { NoData, VirtualTable } from '@cetus/ui-kit'
import { Box, HStack, Spinner, Text, VStack } from '@chakra-ui/react'
import { useDebounceEffect, useDeepCompareEffect } from 'ahooks'
import { useEffect, useMemo, useRef, useState } from 'react'
import ProAuditTips from './ProAuditTips'
import ProCoinBlock from './ProCoinBlock'
import QuickBuyAction from './QuickBuyAction'

type SortRule = 'desc' | 'asc'
export type proListType = {
  label: string
  value: string
}

const PAGE_SIZE = 20

function ProCoinList({ refreshTrigger }: { refreshTrigger: number }) {
  const { getProCoinList, getProCoinListWithCoins } = useGetApiData()
  const { isApp } = useWindowWidth()
  const [isLoading, setIsLoading] = useState(true)
  const [data, setData] = useState<any>()
  const {
    quickCoin,
    quickAmount,
    searchText,
    currentProTab,
    setCurrentProTab,
    displayDateType,
    setCurrentSortTab,
    resetProListStoreData,
    proListParams,
    setProListParams
  } = useProListStore()

  const isFirst = useRef(true)

  const { goToken } = useProHelper()
  const { userCollectObj } = useTokenSelectStore()
  const [watchList, setWatchList] = useState([])
  const { currentAccount, onWalletModal } = useAccountStore()
  const [hasMore, setHasMore] = useState(true)

  const { getUserCollectList } = useTokenSelect()
  const [sortRule, setSortRule] = useState<SortRule>('desc')
  const [sortBy, setSortBy] = useState<proListType>({ label: '24H%', value: 'change' })

  const sortByList = useMemo(() => {
    return [
      { label: `Price/${displayDateType}%`, value: 'price/change' },
      { label: `Price`, value: 'price' },
      { label: `${displayDateType}%`, value: 'change' },
      { label: `Volume (${displayDateType})`, value: 'volume' },
      { label: `MC/FDV`, value: 'market_cap/fdv' },
      { label: `MC`, value: 'market_cap' },
      { label: `FDV`, value: 'fdv' },
      { label: `Liquidity`, value: 'liquidity' },
      { label: `Holders`, value: 'holders' },
      { label: `Age`, value: 'age' }
    ]
  }, [displayDateType])

  const sortByObject = useMemo(
    () =>
      sortByList.reduce((obj: any, item) => {
        obj[item.value] = item
        return obj
      }, {}),
    [sortByList]
  )

  const onParamsChange = (_params: Record<string, any>) => {
    setProListParams({ ..._params })
    setHasMore(true) // Reset hasMore when params change
  }

  const list = useMemo(() => data?.list || [], [data?.list])

  const fetchProData = async (params: ProCoinListFetchParams, isNoLoading = false, limit?: number) => {
    if (currentProTab === 'Watchlist') {
      getWatchList()
      return
    }

    if (!params?.offset && !isNoLoading) {
      setIsLoading(true)
    }

    try {
      const res = await getProCoinList({ ...params, limit: limit || PAGE_SIZE })
      setData(prev => ({
        list: params?.offset !== 0 ? (prev?.list ? prev.list.concat(res.list) : res.list) : res.list
      }))

      setHasMore(limit && limit % 20 === 0 ? true : res.list.length === PAGE_SIZE)
    } finally {
      setIsLoading(false)
      if (isFirst.current) isFirst.current = false
      setTimeout(() => {
        loadingRef.current = false
      }, 300)
    }
  }

  const getWatchList = async () => {
    setIsLoading(true)
    const coins = Object.keys(userCollectObj) || []
    const list = await getProCoinListWithCoins(coins, proListParams?.date_type, proListParams?.text)
    setWatchList(list)
    setIsLoading(false)
  }

  useDeepCompareEffect(() => {
    fetchProData(proListParams)
  }, [proListParams])

  const showList = useMemo(() => (currentProTab === 'Watchlist' ? watchList : data?.list), [currentProTab, data?.list, watchList])

  const observerRef = useRef<IntersectionObserver | null>(null)
  const loadingRef = useRef(false)

  const clickSort = (item: proListType) => {
    loadingRef.current = true

    const scrollElement = document.querySelector('.scroll-container') as HTMLElement | null
    scrollElement?.scrollTo({ top: 0, behavior: 'auto' })

    if (item?.value === sortBy?.value) {
      onParamsChange({
        offset: 0,
        sorted_by: item.value,
        desc: sortRule === 'desc' ? false : true
      })
      setSortRule(sortRule === 'desc' ? 'asc' : 'desc')
    } else {
      onParamsChange({ offset: 0, sorted_by: item.value, desc: true })
      setSortRule('desc')
      setSortBy(item)
    }
  }

  const loadMoreRef = useRef<HTMLDivElement>(null)

  const loadMoreFun = () => {
    loadingRef.current = true
    const nextOffset = list.length
    fetchProData({ ...proListParams, offset: nextOffset })
  }

  useEffect(() => {
    if (!loadMoreRef.current || !hasMore || isLoading || currentProTab === 'Watchlist') return
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !loadingRef.current) {
          loadMoreFun()
        }
      },
      {
        root: null,
        rootMargin: '100px',
        threshold: 0.5
      }
    )

    observer.observe(loadMoreRef.current)
    observerRef.current = observer

    return () => observer.disconnect()
  }, [hasMore, list?.length, currentProTab, proListParams])

  useEffect(() => {
    if (isFirst?.current) return
    if (refreshTrigger && !loadingRef.current) {
      fetchProData({ ...proListParams, offset: 0 }, true, list?.length)
    }
  }, [refreshTrigger])

  useDebounceEffect(
    () => {
      if (isFirst?.current) return
      const searchParams = searchText ? { ...proListParams, text: searchText } : { ...proListParams, text: '' }
      setProListParams(searchParams)
    },
    [searchText],
    { wait: 500 }
  )

  useEffect(() => {
    if (currentProTab === 'Watchlist') {
      setSortBy({})
      getWatchList()
    }
  }, [userCollectObj, currentProTab])

  useEffect(() => {
    if (proListParams?.sorted_by) {
      const sortByItem = sortByObject?.[proListParams.sorted_by]
      setSortBy(sortByItem || {})
      setSortRule(proListParams.desc ? 'desc' : 'asc')
    }

    if (proListParams?.sorted_by === 'volume' && currentProTab === 'Hot Trading') {
      setCurrentProTab('Trending')
    }
    if (proListParams?.sorted_by === 'volume' && proListParams?.desc && currentProTab === 'Trending') {
      setCurrentSortTab('Hot Trading')
    } else if (proListParams?.sorted_by === 'change' && currentProTab === 'Trending') {
      setCurrentSortTab(proListParams?.desc ? 'Gainers' : 'Loser')
    }
  }, [proListParams?.sorted_by, proListParams?.desc])

  useEffect(() => {
    getUserCollectList()
    return () => {
      resetProListStoreData()
    }
  }, [])

  const columns = getColumns(quickCoin, quickAmount, sortBy, sortRule, clickSort, isApp, currentAccount, sortByObject, onWalletModal, currentProTab)

  const gridTemplateColumns = isApp
    ? '140px minmax(90px, 1.3fr) minmax(120px, 1.3fr) minmax(90px, 0.8fr) minmax(60px, 0.8fr) minmax(60px, 0.7fr) minmax(60px,  0.5fr) 60px minmax(28px, 0.35fr)'
    : 'minmax(0px, 2fr) minmax(120px, 1.6fr) minmax(90px, 1.6fr) minmax(90px, 1fr) minmax(90px, 1fr) minmax(90px, 0.7fr) minmax(90px, 0.8fr) 60px minmax(60px, 0.8fr)'

  return (
    <VStack w="100%">
      {!isLoading && showList?.length === 0 ? (
        <NoData
          type="nodata"
          text={currentProTab === 'Watchlist' ? 'No tokens in your watchlist.' : 'No Coins found'}
          children={
            currentProTab === 'Watchlist' ? null : (
              <Text mt="4px" textAlign="center">
                Try adjusting your search or filter settings.
              </Text>
            )
          }
        />
      ) : (
        <>
          <VirtualTable
            columns={columns}
            data={showList}
            rowHeight={66}
            isApp={isApp}
            isLoading={isLoading}
            gridTemplateColumns={gridTemplateColumns}
            stickyHeaderTop="80px"
            onRowClick={(item: any) => goToken(quickCoin?.coin_type, item?.coin_type)}
          />
          {!isLoading && currentProTab !== 'Watchlist' && (
            <Box ref={loadMoreRef} py={4}>
              {hasMore ? (
                <Spinner size="sm" color="text_caption" />
              ) : (
                showList?.length > 0 && <Text fontSize="12px">You've reached the end of the list.</Text>
              )}
            </Box>
          )}
        </>
      )}
    </VStack>
  )
}

const getColumns = (
  quickCoin: Token & { limitBuy: number },
  quickAmount: string,
  sortBy: proListType,
  sortRule: SortRule,
  clickSort: (value: proListType) => void,
  isApp: boolean,
  currentAccount: any,
  sortByObject: any,
  onWalletModal: any,
  currentProTab: string
) => {
  return [
    {
      title: <Text fontSize="12px">Token</Text>,
      key: 'token',
      sticky: true,
      thConfig: {
        w: '20%'
      },
      showLabel: false,
      render: (item: any) => {
        return <ProCoinBlock info={item} />
      }
    },
    {
      title: (
        <TableSortTh
          showSortIcon={currentProTab !== 'Watchlist'}
          labelFontSize="12px"
          appShowIcon={true}
          labelInfo={sortByObject['price/change']}
          sortRule={sortRule}
          sortBy={sortBy}
          clickSort={(value: proListType) => clickSort(value)}
        />
      ),
      key: 'change',
      render: (item: any) => {
        return (
          <VStack gap="4px" align="flex-start">
            <Text fontSize="14px" color="text_caption">
              {item?.price}
            </Text>
            <Text
              fontSize="12px"
              color={
                item?.priceChange == '--' || Number(item?.priceChange) === 0
                  ? 'text_caption'
                  : item?.priceChange?.includes('-')
                    ? 'primary_red'
                    : 'primary_green'
              }
            >
              {item?.priceChange}
            </Text>
          </VStack>
        )
      }
    },
    {
      title: (
        <TableSortTh
          showSortIcon={currentProTab !== 'Watchlist'}
          appShowIcon={true}
          labelFontSize="12px"
          labelInfo={sortByObject['volume']}
          sortRule={sortRule}
          sortBy={sortBy}
          clickSort={(value: proListType) => clickSort(value)}
        />
      ),
      key: 'volume',
      render: (item: any) => {
        return (
          <VStack align="flex-start" gap="4px" w="100%">
            <Text fontSize="14px" color="text_caption">
              {item?.volume}
            </Text>
            <HStack gap="0px" justify="flex-start">
              <Text fontSize="12px" color="primary_green">
                {item?.buyVolume}
              </Text>
              <Text fontSize="12px" color="text_paragraph">
                /
              </Text>
              <Text fontSize="12px" color="primary_red">
                {item?.sellVolume}
              </Text>
            </HStack>
          </VStack>
        )
      }
    },
    {
      title: (
        <TableSortTh
          showSortIcon={currentProTab !== 'Watchlist'}
          appShowIcon={true}
          labelFontSize="12px"
          labelInfo={sortByObject['market_cap/fdv']}
          sortRule={sortRule}
          sortBy={sortBy}
          clickSort={(value: proListType) => clickSort(value)}
        />
      ),
      key: 'fdv',
      render: (item: any) => {
        return (
          <VStack gap="4px" align="flex-start">
            <Text fontSize="14px" color="text_caption">
              {item?.mc}
            </Text>
            <Text fontSize="12px" color="text_paragraph">
              {item?.fdv}
            </Text>
          </VStack>
        )
      }
    },
    {
      title: (
        <TableSortTh
          showSortIcon={currentProTab !== 'Watchlist'}
          appShowIcon={true}
          labelFontSize="12px"
          labelInfo={sortByObject['liquidity']}
          sortRule={sortRule}
          sortBy={sortBy}
          clickSort={(value: proListType) => clickSort(value)}
        />
      ),
      key: 'liquidity'
    },
    {
      title: (
        <TableSortTh
          showSortIcon={currentProTab !== 'Watchlist'}
          appShowIcon={true}
          labelFontSize="12px"
          labelInfo={sortByObject['holders']}
          sortRule={sortRule}
          sortBy={sortBy}
          clickSort={(value: proListType) => clickSort(value)}
        />
      ),
      key: 'holders'
    },
    {
      title: (
        <TableSortTh
          showSortIcon={currentProTab !== 'Watchlist'}
          appShowIcon={true}
          labelFontSize="12px"
          labelInfo={sortByObject['age']}
          sortRule={sortRule}
          sortBy={sortBy}
          clickSort={(value: proListType) => clickSort(value)}
        />
      ),
      key: 'age'
    },
    {
      title: <Text fontSize="12px">Audit</Text>,
      key: 'audit',
      render: (item: any) => {
        return item?.auditTotal === '--' && item?.auditWarningNum == '--' ? (
          <Text fontSize="14px">--</Text>
        ) : (
          <ProAuditTips coinAuditCheckData={item} warningNum={item?.auditWarningNum} total={item?.auditTotal} coinAuditCheckLoading={false} />
        )
      }
    },
    {
      title: (
        <Text fontSize="12px" textAlign="right">
          {isApp ? 'Buy' : 'Quick Buy'}
        </Text>
      ),
      showLabel: false,
      sticky: true,
      key: 'actions',
      render: (item: any) => {
        return (
          <QuickBuyAction quickCoin={quickCoin} quickAmount={quickAmount} info={item} currentAccount={currentAccount} onWalletModal={onWalletModal} />
        )
      }
    }
  ]
}

export default ProCoinList
